using System;using UnityEngine;using Mojinloop.Data; namespace Mojinloop.Combat { public sealed class MonsterSpawner:MonoBehaviour { [SerializeField] MonsterController prefab;[SerializeField] MonsterData data;[SerializeField] Transform spawnPoint;public MonsterController Current{get;private set;} public event Action<MonsterController> Spawned; public void Configure(MonsterController p,MonsterData d,Transform s){prefab=p;data=d;spawnPoint=s;} void Start(){if(Current==null)Spawn();} public void Spawn(){if(Current!=null)Destroy(Current.gameObject);Current=Instantiate(prefab,spawnPoint.position,Quaternion.identity);Current.name="Monster";Current.Initialize(data);Spawned?.Invoke(Current);} } }
